            // Find next occurrence of c in s2
            while (pos2 < s2.length() && s2.charAt(pos2) != c) {
                pos2++;
            }
            if (pos2 < s2.length()) {
                inLcs2[pos2] = true;
                pos2++;
            }
        }
    }

    /**
     * Escapes special markdown characters.
     */
    private static String escapeMarkdown(String s) {
        return s.replace("`", "\\`").replace("*", "\\*").replace("_", "\\_");
