class LcsConfig {

    /**
     * Normalizer preset for configuration.
     */
    enum NormalizerPreset {
        NONE("no normalization", () -> InputNormalizers.none()),
        CASE_INSENSITIVE("lowercase", () -> InputNormalizers.caseInsensitive()),
