                new Scenario("different", "AGGTAB", "GXTXAYB", "Typical comparison"),
                new Scenario("empty", "", "ABC", "Empty string"),
                new Scenario("single", "A", "B", "Single character"),
                new Scenario("no_match", "AAA", "BBB", "No common characters")
        };
    }

    /**
